algorithms.pseudocode:
rate = 500                                   // users admitted per second
every 5 s:
    m = metrics(event)                       // hold p99, 5xx rate, DB CPU
    if m.p99_ms > 300 or m.err > 0.01 or m.db_cpu > 0.7:
        rate = max(100, rate * 0.7)
    elif inventory_remaining(event) == 0:
        close_queue(event, 'SOLD_OUT')
    else:
        rate = min(MAX_RATE, rate + 200)
    redis.incrby(f'serving:{event}', rate * 5)
